describe('Cancel In-Progress Upload', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully cancel an in-progress file upload', () => {
    // Setup: intercept the upload API call
    cy.intercept('POST', '/api/upload').as('uploadRequest');

    // Select a file to upload
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Verify upload progress indicator appears
    cy.get('[data-testid="upload-progress-bar"]').should('be.visible');
    cy.get('[data-testid="upload-status"]').should('contain', 'Uploading');

    // Click cancel button
    cy.get('[data-testid="cancel-upload-button"]').click();

    // Verify cancellation confirmation modal appears
    cy.get('[data-testid="cancel-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="cancel-confirmation-message"]').should('contain', 'Are you sure you want to cancel?');

    // Confirm cancellation
    cy.get('[data-testid="confirm-cancel-button"]').click();

    // Verify upload is cancelled and progress bar is removed
    cy.get('[data-testid="upload-progress-bar"]').should('not.exist');
    cy.get('[data-testid="upload-status"]').should('contain', 'Cancelled');

    // Verify success message is displayed
    cy.get('[data-testid="upload-success-message"]').should('be.visible');
    cy.get('[data-testid="upload-success-message"]').should('contain', 'Upload cancelled successfully');

    // Verify file is no longer in the queue
    cy.get('[data-testid="upload-file-item"]').should('not.exist');
  });

  it('should prevent cancellation when upload is not in progress', () => {
    // Setup: intercept the upload API call
    cy.intercept('POST', '/api/upload').as('uploadRequest');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Wait for upload to complete (or fail)
    cy.wait('@uploadRequest');

    // Verify upload is complete
    cy.get('[data-testid="upload-status"]').should('contain', 'Completed');

    // Attempt to click cancel button
    cy.get('[data-testid="cancel-upload-button"]').should('not.exist');

    // Verify no cancellation modal appears
    cy.get('[data-testid="cancel-confirmation-modal"]').should('not.exist');

    // Verify upload status remains 'Completed'
    cy.get('[data-testid="upload-status"]').should('contain', 'Completed');

    // Verify file is still visible in the upload list
    cy.get('[data-testid="upload-file-item"]').should('be.visible');
  });
});
